shader_type canvas_item;

void fragment() {
	float big = 0.04 * sin(TAU * (UV.x - TIME * 0.4) * 2.0);
	float small = 0.015 * sin(TAU * (UV.x - TIME * 0.7) * 5.0);
	COLOR = texture(TEXTURE, vec2(UV.x, UV.y + big + small));
}

shader_type canvas_item;

uniform sampler2D curve;

void fragment() {
	float k = texture(curve, vec2(fract(TIME * 0.4), 0.0)).r;
	float scale = 1.0 + 0.25 * k;
	vec2 uv = (UV - 0.5) / scale + 0.5;
	COLOR = texture(TEXTURE, uv);
}

shader_type canvas_item;

uniform float wind : hint_range(0.0, 1.0) = 0.0;
uniform float amplitude = 0.06;
uniform float frequency = 3.0;
uniform float speed = 0.5;

void fragment() {
	float cycles = (UV.x - TIME * speed) * frequency;
	float wave = amplitude * wind * sin(TAU * cycles) * UV.x;
	COLOR = texture(TEXTURE, vec2(UV.x, UV.y + wave));
}

